    {label:'4/9 · Complete a task remotely',method:'view.action',params:()=>({paneId:targetId,action:'toggle',args:{id:'remote',done:true}})},
    {label:'5/9 · Rename the target',method:'view.update',params:()=>({paneId:targetId,title:'Renamed from the left panel',data:{}})},
    {label:'6/9 · Move the target below',method:'pane.move',params:()=>({paneId:targetId,targetPaneId:id,direction:'down',ratio:.6})},
    {label:'7/9 · Move it back to the right',method:'pane.move',params:()=>({paneId:targetId,targetPaneId:id,direction:'right',ratio:.46})},
    {label:'8/9 · Delete the target, keep the controller',method:'pane.close',params:()=>({paneId:targetId}),after:()=>controllerSelect(id,'')},
    {label:'9/9 · Create a fresh panel for you',method:'pane.split',params:()=>({...controllerExample(id,'pane.split'),title:'Your next target',data:{content:'# Your turn\n\nThe other panel just created, edited, changed, renamed, moved and deleted a target through real RPC calls.\n\nTry **Write to target**, **Make checklist**, **Complete task**, or **Delete target** from the controller.\n\nOpen a second Viewherd tab to see the same changes sync.'}}),after:response=>controllerSelect(id,response.result.paneId)}
