function demoSteps(context) { return [
  {title:'Start with a clear brief',detail:'Creating a fresh workspace with a useful product document.',method:'workspace.create',params:()=>({label:`Flightline${context.run>1?' · '+context.run:''}`,view:'document',title:'Product brief',data:{content:flightBrief}}),after:response=>Object.assign(context,{workspaceId:response.result.workspaceId,tabId:response.result.tabId,docId:response.result.paneId})},
  {title:'An agent joins the canvas',detail:'Reporting progress through the API so you can see what is happening.',method:'agent.report',params:()=>({id:context.agentId,name:'Viewherd demo agent',status:'working',paneId:context.docId,message:'Turning the brief into a live product workspace.'})},
  {title:'Give the idea a live view',detail:'Splitting the brief to the right and opening a real interactive HTML preview.',method:'pane.split',params:()=>({paneId:context.docId,direction:'right',ratio:.46,view:'preview',title:'Flightline · live preview',data:{html:samplePreview(false)}}),after:response=>Object.assign(context,{previewId:response.result.paneId,splitId:response.result.splitId})},
  {title:'Make the plan concrete',detail:'Appending build decisions directly to the shared document.',method:'view.action',params:()=>({paneId:context.docId,action:'append',args:{content:'\n\n## Build decisions\n\nThe preview now has a working collect button. Next: make upgrades visible and keep launch tasks in their own tab.\n\n**Palette:** warm paper, sage skies, terracotta aircraft.\n\n**Interaction:** every flight should end with a satisfying reward.'}})},
  {title:'Ship the next iteration',detail:'Updating the live view with fleet upgrades. Try its buttons when the demo finishes.',method:'view.action',params:()=>({paneId:context.previewId,action:'set_html',args:{html:samplePreview(true)}})},
  {title:'A launch plan gets its own tab',detail:'Creating a checklist without losing the brief or the preview.',method:'tab.create',params:()=>({workspaceId:context.workspaceId,label:'Launch checklist',view:'tasks',title:'Ready for takeoff',data:{items:[{id:'brief',text:'Write a focused product brief',done:true},{id:'preview',text:'Build an interactive live preview',done:true},{id:'upgrade',text:'Add a visible aircraft upgrade',done:false},{id:'playtest',text:'Playtest collect and upgrade buttons',done:false},{id:'agent',text:'Connect your own agent through the API',done:false}]}}),after:response=>context.tasksId=response.result.paneId},
  {title:'Progress is a shared action',detail:'Completing the upgrade task through view.action. You can check the remaining tasks yourself.',method:'view.action',params:()=>({paneId:context.tasksId,action:'toggle',args:{id:'upgrade',done:true}})},
  {title:'Bring the product back into focus',detail:'Switching back to the original tab by its stable ID.',method:'tab.focus',params:()=>({tabId:context.tabId})},
  {title:'Make space for the product',detail:'Resizing the split so the live preview has room to breathe.',method:'pane.resize',params:()=>({splitId:context.splitId,ratio:.43})},
  {title:'Your turn, captain',detail:'The workspace is yours. Edit, split, play with the preview, or send your own API call.',method:'agent.report',params:()=>({id:context.agentId,name:'Viewherd demo agent',status:'done',paneId:context.previewId,message:'Brief, live preview and launch checklist ready. Your turn.'})}
]; }
let demoRuns=0;
async function runDemo() {
  if(demo&&['running','paused'].includes(demo.status)){toast('The demo is already running. Use Pause or Take over in agent activity.');toggleRail(true);return;}
  closeOverlay();toggleRail(true);
  const context={run:++demoRuns,agentId:`viewherd-demo-${Date.now().toString(36)}`};const activeDemo={status:'running',step:0,completed:0,context,steps:demoSteps(context)};demo=activeDemo;renderDemoStatus();
  try {
    for(let index=0;index<activeDemo.steps.length;index++) {
      while(demo===activeDemo&&activeDemo.status==='paused')await new Promise(resolve=>setTimeout(resolve,150));
      if(demo!==activeDemo||activeDemo.status!=='running')break;
      activeDemo.step=index;renderDemoStatus();await new Promise(resolve=>setTimeout(resolve,index===0?350:1050));
      while(demo===activeDemo&&activeDemo.status==='paused')await new Promise(resolve=>setTimeout(resolve,150));
      if(demo!==activeDemo||activeDemo.status!=='running')break;
      const step=activeDemo.steps[index];const response=await call(step.method,step.params(),{actor:'demo-agent'});step.after?.(response);activeDemo.completed=index+1;if(demo===activeDemo)renderDemoStatus();
    }
    if(demo===activeDemo&&activeDemo.status==='running'){activeDemo.status='done';renderDemoStatus();toast('The agent handed you a working canvas. Try the preview, edit the brief, or open the checklist.');}
  }catch(error){if(demo===activeDemo){activeDemo.status='error';activeDemo.error=error.message;renderDemoStatus();}}
}
function renderDemoStatus() {
  const node=$('#demo-status');if(!demo)return;
  if(['running','paused'].includes(demo.status)){const step=demo.steps[demo.step];node.innerHTML=`<div class="demo-running"><div class="demo-kicker">SCRIPTED AGENT DEMO · ${demo.step+1}/${demo.steps.length}</div><h3 class="demo-step">${esc(step.title)}</h3><div class="demo-detail">${esc(step.detail)}</div><div class="demo-progress"><span style="width:${demo.completed/demo.steps.length*100}%"></span></div><div class="demo-controls"><button id="demo-pause">${icon(demo.status==='paused'?'play':'pause')}${demo.status==='paused'?'Resume':'Pause'}</button><button id="demo-takeover" class="take-over">${icon('move')}Take over</button><button id="demo-cancel">${icon('close')}Stop</button></div><span class="demo-disclosure">${demo.status==='paused'?'Paused. Make the canvas your own.':esc(step.method)+' → real shared state'}</span></div>`;$('#demo-pause').addEventListener('click',()=>{demo.status=demo.status==='paused'?'running':'paused';renderDemoStatus();});$('#demo-takeover').addEventListener('click',()=>stopDemo(true));$('#demo-cancel').addEventListener('click',()=>stopDemo(false));$('#run-demo').innerHTML=`${icon('play')}<span>Demo running</span>`;}
  else { const done=demo.status==='done';node.innerHTML=`<div class="demo-kicker">${done?'THE CANVAS IS YOURS':demo.status==='error'?'DEMO PAUSED':'HUMAN IN CONTROL'}</div><h3>${done?'From an idea<br>to a shared workspace.':'Pick up where<br>the agent left off.'}</h3><p>${done?'Try the preview. Edit the brief.<br>Open the launch checklist.':esc(demo.error||'Your changes stay in the workspace. The agent has stopped making calls.')}</p><div class="demo-complete">${icon('check')}${demo.completed} real API calls · ${done?'handoff complete':'workspace preserved'}</div><button class="demo-finish-link" id="demo-inspect">${icon('terminal')}Inspect the API calls ${icon('arrow-up-right')}</button><span class="demo-disclosure">Scripted demo · bring your own agent next</span>`;$('#demo-inspect').addEventListener('click',openConsole);$('#run-demo').innerHTML=`${icon('play')}<span>Run again</span>`; }
}
function stopDemo(takeover) { if(!demo)return;demo.status=takeover?'taken-over':'stopped';renderDemoStatus();if(demo.context?.docId)fire('agent.report',{id:demo.context.agentId,name:'Viewherd demo agent',status:'idle',paneId:demo.context.previewId||demo.context.docId,message:takeover?'Human took over the workspace.':'Demo stopped. Workspace preserved.'},{actor:'demo-agent'});toast(takeover?'You have the canvas. The demo has stopped.':'Demo stopped. Your workspace stays here.'); }
function toggleRail(force) { const shell=$('#shell');if(window.innerWidth<=760){shell.classList.toggle('mobile-rail-open',force??!shell.classList.contains('mobile-rail-open'));}else{shell.classList.toggle('rail-hidden',force===undefined?!shell.classList.contains('rail-hidden'):!force);} }

$('#panel-control-demo').addEventListener('click',openPanelControlDemo);
$('#new-workspace').addEventListener('click',newWorkspace);$('#add-tab').addEventListener('click',newTab);$('#add-view').addEventListener('click',()=>chooseView(view=>openNewView(view)));$('#split-right').addEventListener('click',()=>chooseView(view=>openNewView(view)));$('#workspace-more').addEventListener('click',event=>workspaceMenu(event.currentTarget));$('#run-demo').addEventListener('click',runDemo);$('#rail-run-demo').addEventListener('click',runDemo);$('#agent-toggle').addEventListener('click',()=>toggleRail());$('#open-console').addEventListener('click',openConsole);$('#keyboard-help').addEventListener('click',openPalette);$('#status-palette').addEventListener('click',openPalette);$('#api-guide').addEventListener('click',()=>openNewView('api'));$('#mobile-menu').addEventListener('click',()=>$('#shell').classList.toggle('sidebar-open'));
document.addEventListener('keydown',event=>{if((event.metaKey||event.ctrlKey)&&event.key.toLowerCase()==='k'){event.preventDefault();activeOverlay?.type==='palette'?closeOverlay():openPalette();}if(event.key==='Escape'){closeOverlay();$('#shell').classList.remove('sidebar-open','mobile-rail-open');}if((event.metaKey||event.ctrlKey)&&event.shiftKey&&event.key==='\\'){event.preventDefault();chooseView(view=>openNewView(view));}});
document.addEventListener('pointerdown',event=>{if($('#shell').classList.contains('sidebar-open')&&!event.target.closest('.sidebar')&&!event.target.closest('#mobile-menu'))$('#shell').classList.remove('sidebar-open');});
document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='visible')refresh();});
let resizeScheduled=false;new ResizeObserver(()=>{if(resizeScheduled)return;resizeScheduled=true;requestAnimationFrame(()=>{resizeScheduled=false;if(state)renderCanvas(currentTab(),paneIds(currentTab()?.layout));});}).observe($('#pane-canvas'));
await refresh();
fetch('/api/schema').then(response=>response.json()).then(body=>{apiMethods=body.methods||body.result?.methods||[];}).catch(()=>{});
setInterval(refresh,1000);
if(!state){$('#pane-canvas').innerHTML=`<div class="loading-state">${icon('radio')}<h2>Waiting for the workspace</h2><p>Reconnecting to the API. Your canvas will appear here.</p><button class="primary-small" id="retry-connect">Reconnect</button></div>`;$('#retry-connect').addEventListener('click',refresh);}
